    private final String name;

    protected PricingRule(String name) {
        this.name = name;
    }

    public final int quote(int quantity) {
        if (quantity <= 0) {
            return 0;
        }
        int gross = unitPriceCents() * quantity;
        int off = discountCents(quantity, gross);
        if (off < 0) {
            off = 0;
        }
        if (off > gross) {
            off = gross;
        }
        return gross - off;
    }

    /** Step 1: what one unit costs, in cents. */
    protected abstract int unitPriceCents();

    /** Step 2: how much comes off. The default rule never discounts. */
    protected int discountCents(int quantity, int grossCents) {
        return 0;
    }

    public final String getName() {
        return name;
    }
}

