public class BulkPricingRuleTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String nameOf(PricingRule rule) {
        return rule == null ? "none" : rule.getName();
    }

    public static void main(String[] args) {
        try {
            PricingRule flat = new FlatPricingRule("flat");
            PricingRule bulk = new BulkPricingRule("bulk");

            check("bulk unit price shows through the template", 250, bulk.quote(1));
            check("small order gets no discount", 2000, bulk.quote(8));
            check("ten units get 10 percent off", 2250, bulk.quote(10));
            check("fifty units get 20 percent off", 10000, bulk.quote(50));
            check("zero units cost nothing", 0, bulk.quote(0));
            check("negative units cost nothing", 0, bulk.quote(-3));
            check("the provided flat rule is untouched", 2500, flat.quote(10));

            PricingRule[] rules = { flat, bulk, null };
            check("cheapest at 10 is bulk", "bulk", nameOf(BulkPricingRule.cheapest(rules, 10)));
            check("cheapest at 1 keeps the earlier tie", "flat", nameOf(BulkPricingRule.cheapest(rules, 1)));
            check("cheapest of an empty array", "none",
                    nameOf(BulkPricingRule.cheapest(new PricingRule[0], 5)));
            check("cheapest of null", "none", nameOf(BulkPricingRule.cheapest(null, 5)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

