public class BulkPricingRule extends PricingRule {

    public BulkPricingRule(String name) {
        super(name);
    }

    @Override
    protected int unitPriceCents() {
        return 250;
    }

    @Override
    protected int discountCents(int quantity, int grossCents) {
        if (quantity >= 50) {
            return grossCents * 20 / 100;
        }
        if (quantity >= 10) {
            return grossCents * 10 / 100;
        }
        return 0;
    }

    public static PricingRule cheapest(PricingRule[] rules, int quantity) {
        if (rules == null) {
            return null;
        }
        PricingRule best = null;
        for (PricingRule rule : rules) {
            if (rule == null) {
                continue;
            }
            if (best == null || rule.quote(quantity) < best.quote(quantity)) {
                best = rule;
            }
        }
        return best;
    }
}
